CREATE TYPE "WhatsAppCampaignStatus" AS ENUM ('DRAFT', 'SCHEDULED', 'CANCELLED');
CREATE TYPE "WhatsAppCampaignRecipientStatus" AS ENUM ('ELIGIBLE', 'EXCLUDED');
CREATE TABLE "whatsapp_campaigns" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"templateDefinitionId" TEXT NOT NULL,"name" TEXT NOT NULL,"status" "WhatsAppCampaignStatus" NOT NULL DEFAULT 'DRAFT',"audienceFilters" JSONB NOT NULL,"scheduledAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "whatsapp_campaigns_pkey" PRIMARY KEY ("id"));
CREATE TABLE "whatsapp_campaign_stores" ("id" TEXT NOT NULL,"campaignId" TEXT NOT NULL,"storeId" TEXT NOT NULL,"senderId" TEXT NOT NULL,CONSTRAINT "whatsapp_campaign_stores_pkey" PRIMARY KEY ("id"));
CREATE TABLE "whatsapp_campaign_recipients" ("id" TEXT NOT NULL,"campaignId" TEXT NOT NULL,"contactId" TEXT NOT NULL,"status" "WhatsAppCampaignRecipientStatus" NOT NULL,"exclusionReason" TEXT,"snapshot" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "whatsapp_campaign_recipients_pkey" PRIMARY KEY ("id"));
CREATE INDEX "whatsapp_campaigns_organizationId_createdAt_idx" ON "whatsapp_campaigns"("organizationId","createdAt");CREATE INDEX "whatsapp_campaigns_organizationId_status_idx" ON "whatsapp_campaigns"("organizationId","status");CREATE UNIQUE INDEX "whatsapp_campaign_stores_campaignId_storeId_key" ON "whatsapp_campaign_stores"("campaignId","storeId");CREATE INDEX "whatsapp_campaign_stores_senderId_idx" ON "whatsapp_campaign_stores"("senderId");CREATE UNIQUE INDEX "whatsapp_campaign_recipients_campaignId_contactId_key" ON "whatsapp_campaign_recipients"("campaignId","contactId");CREATE INDEX "whatsapp_campaign_recipients_campaignId_status_idx" ON "whatsapp_campaign_recipients"("campaignId","status");CREATE INDEX "whatsapp_campaign_recipients_contactId_idx" ON "whatsapp_campaign_recipients"("contactId");
ALTER TABLE "whatsapp_campaigns" ADD CONSTRAINT "whatsapp_campaigns_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "organizations"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "whatsapp_campaigns" ADD CONSTRAINT "whatsapp_campaigns_templateDefinitionId_fkey" FOREIGN KEY ("templateDefinitionId") REFERENCES "whatsapp_template_definitions"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "whatsapp_campaign_stores" ADD CONSTRAINT "whatsapp_campaign_stores_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "whatsapp_campaigns"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "whatsapp_campaign_stores" ADD CONSTRAINT "whatsapp_campaign_stores_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "stores"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "whatsapp_campaign_stores" ADD CONSTRAINT "whatsapp_campaign_stores_senderId_fkey" FOREIGN KEY ("senderId") REFERENCES "store_whatsapp_senders"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "whatsapp_campaign_recipients" ADD CONSTRAINT "whatsapp_campaign_recipients_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "whatsapp_campaigns"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "whatsapp_campaign_recipients" ADD CONSTRAINT "whatsapp_campaign_recipients_contactId_fkey" FOREIGN KEY ("contactId") REFERENCES "whatsapp_contacts"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
